/**
 * In-memory D1 stand-in for backend-accounts tests. Runs the real migration
 * files from migrations/ on SQLite (node:sqlite, the same engine family as D1)
 * and exposes the D1 surface the Worker uses: prepare/bind/first/all/run and
 * batch. Batches are transactional (all or nothing) and serialized, as D1
 * serializes writes, so concurrency tests exercise the same guarantees.
 *
 * All credentials and staff records created here are generated by the tests.
 */
import { createRequire } from "node:module";
import { readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { argon2id } from "hash-wasm";

const nodeRequire = createRequire(import.meta.url);
const { DatabaseSync } = nodeRequire("node:sqlite") as typeof import("node:sqlite");
type Sqlite = InstanceType<typeof DatabaseSync>;

const MIGRATIONS_DIR = fileURLToPath(new URL("../../migrations", import.meta.url));

type Bindable = string | number | bigint | null | Uint8Array;

class Statement {
  private params: Bindable[] = [];
  constructor(private readonly db: Sqlite, private readonly sql: string) {}

  bind(...params: unknown[]): Statement {
    this.params = params.map((value) => {
      if (value === undefined) throw new Error("D1 cannot bind undefined");
      if (typeof value === "boolean") return value ? 1 : 0;
      return value as Bindable;
    });
    return this;
  }

  async first<T = Record<string, unknown>>(column?: string): Promise<T | null> {
    const row = this.db.prepare(this.sql).get(...this.params) as Record<string, unknown> | undefined;
    if (!row) return null;
    return (column ? row[column] : row) as T;
  }

  async all<T = Record<string, unknown>>(): Promise<{ results: T[]; success: true; meta: { changes: number } }> {
    const results = this.db.prepare(this.sql).all(...this.params) as T[];
    return { results, success: true, meta: { changes: 0 } };
  }

  async run(): Promise<{ success: true; meta: { changes: number } }> {
    const info = this.db.prepare(this.sql).run(...this.params);
    return { success: true, meta: { changes: Number(info.changes) } };
  }

  /** Executes one batch member and returns a D1-shaped result. */
  runForBatch(): { success: true; results: unknown[]; meta: { changes: number } } {
    const stmt = this.db.prepare(this.sql);
    if (/^\s*select\b/i.test(this.sql) || /\breturning\b/i.test(this.sql)) {
      const results = stmt.all(...this.params) as unknown[];
      return { success: true, results, meta: { changes: 0 } };
    }
    const info = stmt.run(...this.params);
    return { success: true, results: [], meta: { changes: Number(info.changes) } };
  }
}

export class SqliteD1 {
  private queue: Promise<unknown> = Promise.resolve();
  constructor(readonly sqlite: Sqlite) {}

  prepare(sql: string): Statement {
    return new Statement(this.sqlite, sql);
  }

  batch(statements: Statement[]): Promise<Array<ReturnType<Statement["runForBatch"]>>> {
    const run = async () => {
      this.sqlite.exec("BEGIN IMMEDIATE");
      try {
        const results = statements.map((statement) => statement.runForBatch());
        this.sqlite.exec("COMMIT");
        return results;
      } catch (error) {
        this.sqlite.exec("ROLLBACK");
        throw error;
      }
    };
    // Serialize batches: each one starts after the previous one has finished.
    const next = this.queue.then(run, run);
    this.queue = next.catch(() => undefined);
    return next;
  }

  /** Read-only helper for assertions. */
  rows<T = Record<string, unknown>>(sql: string, ...params: Bindable[]): T[] {
    return this.sqlite.prepare(sql).all(...params) as T[];
  }

  scalar(sql: string, ...params: Bindable[]): unknown {
    const row = this.sqlite.prepare(sql).get(...params) as Record<string, unknown> | undefined;
    return row ? Object.values(row)[0] : undefined;
  }
}

export function openMigratedDb(): SqliteD1 {
  const sqlite = new DatabaseSync(":memory:");
  sqlite.exec("PRAGMA foreign_keys = ON");
  for (const file of readdirSync(MIGRATIONS_DIR).filter((f) => f.endsWith(".sql")).sort()) {
    sqlite.exec(readFileSync(`${MIGRATIONS_DIR}/${file}`, "utf8"));
  }
  return new SqliteD1(sqlite);
}

/** Same Argon2id parameters as the Worker's hashPassword. */
export async function fixtureHash(password: string): Promise<string> {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return String(await argon2id({ password, salt, parallelism: 1, iterations: 3, memorySize: 65536, hashLength: 32, outputType: "encoded" }));
}

/** Random fixture password. Never a fixed literal, never printed. */
export function fixturePassword(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  return Array.from(bytes, (b) => b.toString(36).padStart(2, "0")).join("").slice(0, 32);
}

export async function seedOrganization(db: SqliteD1, id: string, active = true): Promise<void> {
  const now = Date.now();
  await db.prepare("INSERT INTO organizations(id,name,is_active,created_at,updated_at) VALUES(?,?,?,?,?)")
    .bind(id, `Org ${id}`, active ? 1 : 0, now, now).run();
}

export async function seedUser(db: SqliteD1, options: {
  id: string; username: string; organizationId: string; role: "ORGANIZATION_ADMIN" | "STAFF";
  password: string; email?: string | null; onyxId?: string | null; mustChange?: boolean;
}): Promise<void> {
  const now = Date.now();
  await db.prepare(`INSERT INTO users(id,username,email,organization_id,password_hash,is_admin,is_active,class,role,parent_user_id,created_at,updated_at,onyx_id,must_change_password)
    VALUES(?,?,?,?,?,?,1,NULL,?,?,?,?,?,?)`).bind(
    options.id, options.username, options.email ?? null, options.organizationId, await fixtureHash(options.password),
    options.role === "ORGANIZATION_ADMIN" ? 1 : 0, options.role, "__allfather__", now, now,
    options.onyxId ?? null, options.mustChange ? 1 : 0,
  ).run();
}
